<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {readSubmissionObservation} from './submission-observation.ts';import {ElButton} from 'element-plus';import {useDesktop} from './store.ts';
const store=useDesktop(),error=ref(''),busy=ref(false),queue=ref<Record<string,any>>({}),scheduler=ref<Record<string,any>>({}),attempts=ref<Record<string,any>[]>([]),queueEnabled=ref(false),limit=ref(1),scheduleEnabled=ref(false),pollSeconds=ref(15),connectionId=ref(''),threadId=ref(''),prompt=ref(''),confirm=ref(false);
const notifications=ref<Record<string,any>>({}),notifyEnabled=ref(false),notifyAllDay=ref(true),notifyStart=ref('09:00'),notifyEnd=ref('22:00');
async function run(work:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await work();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function load(){queue.value=await store.request('queue.get');scheduler.value=await store.request('scheduler.settings.get');attempts.value=(await store.request('attempts.list',{limit:200})).items as Record<string,any>[];queueEnabled.value=queue.value.enabled;limit.value=queue.value.limit;scheduleEnabled.value=scheduler.value.enabled;pollSeconds.value=scheduler.value.pollSeconds;notifications.value=await store.request('notifications.settings.get');notifyEnabled.value=notifications.value.enabled;notifyAllDay.value=notifications.value.dailyWindow.allDay;notifyStart.value=notifications.value.dailyWindow.start??'09:00';notifyEnd.value=notifications.value.dailyWindow.end??'22:00';}
onMounted(()=>void run(async()=>{connectionId.value=String((await store.request('connections.get')).connectionId);await load();}));
async function saveQueue(){await run(async()=>{await store.request('queue.configure',{expectedRevision:queue.value.revision,enabled:queueEnabled.value,limit:limit.value},crypto.randomUUID());await load();});}
async function saveSchedule(){await run(async()=>{await store.request('scheduler.settings.update',{expectedRevision:scheduler.value.revision,enabled:scheduleEnabled.value,pollSeconds:pollSeconds.value},crypto.randomUUID());await load();});}
async function tick(){await run(async()=>{await store.request('scheduler.runNow',{},crypto.randomUUID());await load();});}
async function send(){await run(async()=>{if(!confirm.value)throw new Error('请明确确认本次目标和消息发送');const threadRef={connectionId:connectionId.value,threadId:threadId.value},observed=await readSubmissionObservation(store.request,threadRef);await store.request('threads.send',{threadRef,prompt:prompt.value,connectionRevision:observed.connectionRevision,expectedLatestTurnId:(observed.latestTurn as any)?.id??null,confirm:true},crypto.randomUUID());confirm.value=false;await load();});}
async function reconcile(id:string){await run(async()=>{await store.request('attempts.reconcile',{id},crypto.randomUUID());await load();});}
async function reorder(id:string,direction:string){await run(async()=>{await store.request('tasks.reorder',{id,direction,expectedQueueRevision:queue.value.revision},crypto.randomUUID());await load();});}
async function saveNotifications(){await run(async()=>{await store.request('notifications.settings.update',{expectedRevision:notifications.value.revision,patch:{enabled:notifyEnabled.value,dailyWindow:notifyAllDay.value?{allDay:true}:{allDay:false,start:notifyStart.value,end:notifyEnd.value}}},crypto.randomUUID());await load();});}
</script>
<template><section class="panel"><h2>统一调度与并发槽位</h2><p class="notice">主动推进可能投递已经授权的任务；只读刷新不会推进。高优先级不抢占已提交轮次。{{store.mode==='fixture'?'当前为模拟投递。':'真实投递必须通过绑定和旧版锁门禁。'}}</p><p role="alert" v-if="error">{{error}}</p><label><input v-model="queueEnabled" type="checkbox" aria-label="启用并发队列" />启用并发队列</label><label>最大并发槽位<input v-model.number="limit" type="number" min="1" max="20" aria-label="并发槽位上限" /></label><p>已占槽 {{queue.held??'未知'}} · 队列修订 {{queue.revision}}</p><ElButton :disabled="busy" @click="saveQueue">保存队列设置</ElButton>
 <label><input v-model="scheduleEnabled" type="checkbox" aria-label="启用独立任务调度" />启用独立任务周期</label><label>任务检查间隔（秒）<input v-model.number="pollSeconds" type="number" min="10" max="300" aria-label="任务检查间隔" /></label><ElButton :disabled="busy" @click="saveSchedule">保存任务周期</ElButton><ElButton :disabled="busy" @click="tick">主动推进已授权任务一次</ElButton><ElButton :disabled="busy" @click="run(load)">只读刷新队列与投递</ElButton>
 <ol><li v-for="item in queue.items||[]" :key="item.id">{{item.threadRef.threadId}} · {{item.priority}} · {{item.enabled?'启用':'暂停'}}<ElButton @click="reorder(item.id,'up')">同级上移</ElButton><ElButton @click="reorder(item.id,'down')">同级下移</ElButton></li></ol></section>
 <section class="panel"><h2>通知</h2><p class="muted">仅观察额度恢复、任务完成及卡片结果；通知不含提示词、账号或完整卡号。通知失败不回滚业务。</p><label><input v-model="notifyEnabled" type="checkbox" aria-label="启用业务通知" />启用业务通知</label><label><input v-model="notifyAllDay" type="checkbox" />全天允许通知</label><template v-if="!notifyAllDay"><label>允许通知开始<input v-model="notifyStart" type="time" /></label><label>允许通知结束<input v-model="notifyEnd" type="time" /></label></template><ElButton :disabled="busy" @click="saveNotifications">保存通知设置</ElButton></section>
 <section class="panel"><h2>显式单次发送</h2><p class="muted">仅限无托管、无 Goal、无审批、无运行轮次和无未决意图的空闲会话。已受托管目标请使用任务授权流程。</p><label>连接 ID<input v-model="connectionId" aria-label="单次发送连接 ID" /></label><label>会话 ID<input v-model="threadId" aria-label="单次发送会话 ID" /></label><label>消息<textarea v-model="prompt" aria-label="单次发送消息" rows="3" maxlength="10000"></textarea></label><label><input v-model="confirm" type="checkbox" aria-label="明确确认单次发送" />我确认向所填目标发送这条消息一次</label><ElButton :disabled="busy||!confirm||!threadId||!prompt" @click="send">确认单次发送</ElButton></section>
 <section class="panel"><h2>投递、回执与轮次</h2><article v-for="item in attempts" :key="item.id" class="panel"><p class="mono">{{item.id}} · {{item.threadRef.threadId}}</p><p>{{item.state}} · 槽位 {{item.slot}} · 已提交 {{item.submitted?'是':'未证实'}} · 回执匹配 {{item.receiptMatched?'是':'否'}} · 轮次 {{item.turnId||'未知'}}</p><ElButton v-if="item.slot==='held'" :disabled="busy" @click="reconcile(item.id)">仅核对原投递</ElButton></article><p v-if="!attempts.length">暂无投递意图。</p></section></template>
